"""Explain atomic set races, MMIO boundaries, progress and code generation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1565': ('숫자판을 고치는 담당자가 문을 잠갔는데, 다른 사람이 옆문으로 들어와 숫자를 바꾸면 잠근 보람이 없어요. 함께 쓰는 숫자판의 규칙은 바꾸는 사람 모두가 지켜야 해요.', 'set과 조건부 덧셈이 같은 객체의 원자성을 함께 지켜야 하는 이유를 이해합니다.', '시작 1에서 두 순서를 그리세요. set(0) → 조건 덧셈 건너뜀 → 0, 조건 덧셈 2 → set(0) → 0이에요.', ['이번 예시의 숫자판은 1로 시작해요. A는 “0이 아니면 1 더하기”인 add_unless를 하고, B는 “0 저장하기”인 set을 해요. 다른 갱신 없이 두 작업이 모두 끝난 뒤의 숫자를 알아봐요.', 'B가 먼저 끝나면 숫자판은 0이에요. 다음 A는 0인지 검사하고, 0이므로 더하지 않아요. 마지막 값은 0이에요.', 'A가 먼저 끝나면 1에 1을 더해 잠깐 2가 돼요. 다음 B가 0을 저장하므로 마지막 값은 0이에요. 중간에 2를 거치는 것과 두 작업이 끝난 최종 값이 2인 것은 달라요.', '두 연산의 원자성을 지킨다면 위 두 순서로 설명할 수 있어야 해요. 최종 값 2는 허용되지 않아요. 그런데 A가 1을 읽은 중간에 B가 보호 규칙을 우회해 0을 쓰고, A가 옛 값 1로 계산한 2를 쓰면 이 금지 결과가 생겨요.', '잠금으로 원자 연산을 구현하는 경우 set도 그 보호와 맞아야 해요. lib/atomic64.c의 generic_atomic64_set은 객체 주소로 잠금을 고르고, 잠근 뒤 counter에 값을 쓰고 풀어요. 해당 객체의 다른 갱신과 같은 잠금 선택 규칙을 사용하는 이유예요.', '원자 API로 관리하는 counter에 함부로 직접 대입을 섞으면 안 돼요. CPU마다 구현 방법은 달라도 같은 객체의 원자성 약속은 지켜야 해요. 종이에 두 순서를 계산하는 것은 이유를 이해하는 연습이며 실제 여러 CPU에서 모든 실행을 검증한 것은 아니에요.'], [('시작 1에서 “0이 아니면 1 더하기”와 “0 저장하기”를 각각 한 번 했어요. 둘 다 끝난 최종 값이 2여도 되나요?', ['네. 각 호출이 원자적이면 마지막 값은 무엇이든 괜찮아요', '아니요. 올바른 두 순서에서는 모두 마지막 값이 0이에요'], '정답은 두 번째예요. 저장이 먼저면 더하기를 건너뛰고, 더하기가 먼저면 나중 저장이 0으로 덮어요. 중간 값 2와 최종 값 2를 구별하세요.'), ('RMW가 잠금으로 보호되는 구현에서 set이 그 보호를 우회해도 되나요?', ['아니요. set도 같은 객체의 원자성을 깨지 않는 보호 방법을 따라야 해요', '네. set은 어떤 구현에서도 직접 대입만 하면 충분해요'], '정답은 첫 번째예요. set이 중간에 끼어들면 옛 값으로 계산한 결과가 뒤늦게 저장될 수 있어요. generic atomic64의 set도 같은 주소 기반 잠금을 사용하는 이유예요.')]), 'os1566': ('공책에 숫자를 적는 칸과 기계를 움직이는 버튼은 모양이 비슷해도 다르게 다뤄야 해요. 주소로 접근하는 곳도 보통 메모리인지 장치인지에 따라 규칙이 달라요.', '일반 메모리의 원자 연산과 장치 레지스터 접근의 차이를 이해합니다.', '“보통 메모리의 counter → 지원되는 atomic API”, “장치 레지스터 → 장치 규칙과 I/O API 확인”의 두 화살표를 그리세요.', ['MMIO는 Memory-Mapped I/O의 줄임말이에요. 장치의 상태를 읽거나 명령을 보내는 곳을 주소로 접근하게 만든 방식이에요. 주소가 있다고 모두 일반 메모리의 숫자 칸과 같은 것은 아니에요.', '장치 레지스터는 장치와 정보를 주고받는 작은 창구처럼 생각할 수 있어요. 어떤 창구는 읽으면 상태가 지워지고, 어떤 창구는 특정 값을 쓰면 동작을 시작할 수 있어요. 모든 레지스터가 그런 것은 아니므로 해당 장치의 규칙을 읽어야 해요.', 'atomic 문서는 MMIO에 대한 원자 연산을 지원하지 않는다고 명시해요. 일부 환경에서는 심각한 하드웨어 예외로 실행이 중단될 수도 있다고 설명해요. 일반 메모리 counter용 원자적 더하기를 장치 주소에 그대로 적용하면 안 돼요.', '포인터는 위치를 가리키는 값이고 cast는 그 값을 다른 자료형으로 취급하도록 적는 C 표현이에요. 장치 주소를 atomic_long_t 포인터로 cast해도 장치가 일반 RAM으로 변하지 않아요. 이름표를 갈아 붙인다고 기계 버튼이 공책 칸으로 바뀌지 않는 것과 같아요.', '접근 폭은 한 번에 몇 비트를 읽거나 쓰는지예요. 장치가 요구하는 폭, 순서, 읽기·쓰기의 부작용을 맞춰야 해요. 그래서 장치와 드라이버의 I/O 접근 API 규칙을 함께 확인해요. I/O는 입력과 출력이라는 뜻이에요.', '원자성이 필요하다는 이유만으로 아무 주소에 atomic API를 쓰지는 마세요. 그 API가 지원하는 메모리 객체인지 먼저 확인해요. 이 수업은 장치 접근 코드를 실행하는 실습이 아니라, 주소의 성격에 따라 도구를 구별하는 읽기 연습이에요.'], [('장치 MMIO 주소를 atomic_long_t 포인터로 cast하면 원자적 더하기를 써도 되나요?', ['네. 포인터 자료형만 맞추면 모든 장치에서 가능해요', '아니요. 문서는 MMIO의 atomic 연산을 지원하지 않아요'], '정답은 두 번째예요. cast는 C에서 주소를 취급하는 자료형을 바꿀 뿐 하드웨어의 기능을 바꾸지 않아요. 일부 환경에서는 심각한 예외까지 생길 수 있어요.'), ('장치 레지스터를 읽을 때 접근 폭과 부작용은 무엇을 따라야 하나요?', ['해당 장치의 설명과 I/O 접근 API의 규칙을 따라야 해요', '일반 숫자 counter의 증가 규칙만 보면 돼요'], '정답은 첫 번째예요. 장치 창구는 읽기만 해도 상태가 바뀌는 등 별도 동작이 있을 수 있어요. 일반 메모리의 숫자 칸과 같은 규칙이라고 가정하면 안 돼요.')]), 'os1567': ('여러 사람이 동시에 문으로 들어가려다 서로 양보하고 다시 시도하는 모습을 떠올려 보세요. 한 번의 시도가 규칙에 맞는 것과 모두 언젠가 들어가는 것은 다른 문제예요.', '원자적 재시도의 올바름과 결국 일을 마치는 진행성을 구별합니다.', '“비교 → 실패 → 새 값으로 다시 계산 → 재시도”를 그리세요. 옆에 “몇 번 성공한 실험만으로 모든 경우의 종료를 증명하지 못함”이라고 적으세요.', ['CAS는 Compare And Swap, 즉 예상한 값과 같으면 새 값으로 바꾸는 비교 교체예요. 다른 CPU가 먼저 바꾸면 비교에 실패할 수 있어서 새로 관찰한 값으로 다시 계산하고 시도하는 반복문을 만들어요.', '진행성은 이런 작업이 계속 시도만 하지 않고 실제로 앞으로 나아가는 성질이에요. 어떤 작업이 계속 기회를 얻지 못하면 기아라고 불러요. 계산을 잘못하지 않는 원자성과 결국 완료하는 진행성은 서로 다른 질문이에요.', '일부 CPU는 LL/SC라는 명령 쌍으로 원자 연산을 구현해요. LL은 값을 읽으면서 저장을 시도할 조건을 마련하고, SC는 그 조건이 유지될 때 저장해요. 이 조건을 예약이라고도 해요. 예약은 다른 사람이 손대지 못하도록 계속 잠가 두는 자물쇠가 아니에요.', 'LL/SC 자체에 진행을 위한 보장이 있더라도, 그것으로 만든 C의 CAS 반복문 전체가 같은 보장을 자동으로 받지는 않아요. 어떤 CPU에서는 비교 실패 뒤의 분기나 컴파일러가 만든 코드도 LL/SC의 성공 조건에 영향을 줄 수 있다고 문서가 설명해요.', '문서는 영향을 받는 구현에 실패 뒤 기다리는 간격을 늘리는 exponential backoff를 권해요. 예를 들어 충돌을 줄이려고 재시도 간격을 점차 늘리는 생각이에요. 실제 방법은 해당 CPU와 구현을 검토해야 하며 모든 사용자 반복문에 무작정 대기를 넣으라는 뜻은 아니에요.', '네 작업을 함께 실행한 실험이 끝났다면 그 실행에서 완료를 관찰한 것이에요. 가능한 모든 실행 순서에서 아무도 영원히 기다리지 않는다는 증명은 아니에요. 특정 테스트의 결과와 모든 상황에 대한 보장을 구별하세요. 이 수업에서는 그 차이를 원문으로 배우며 새 동시 실행 실험을 했다고 주장하지 않아요.'], [('LL/SC 명령의 진행 보장이 있으면 그것으로 만든 CAS C 반복문 전체도 자동으로 기아가 없다고 결론 내려도 되나요?', ['네. 명령의 보장이 어떤 반복문에도 그대로 적용돼요', '아니요. 분기와 컴파일된 코드가 성공 조건에 미치는 영향도 봐야 해요'], '정답은 두 번째예요. 작은 명령 쌍의 약속과 그 주위의 계산·분기를 포함한 반복문의 약속은 달라요. 문서는 일부 CPU에서 이런 차이가 진행을 방해할 수 있다고 설명해요.'), ('네 작업의 동시 실행 실험이 한 번 끝났어요. 모든 실행에서 기아가 없다는 증명인가요?', ['아니요. 확인한 그 실행이 끝났다는 증거예요', '네. 한 번 끝났으면 모든 실행 순서에서 공정해요'], '정답은 첫 번째예요. 실행 순서와 경쟁 상황은 다양해요. 특정 실험의 완료는 유용하지만 가능한 모든 상황의 종료와 공정성까지 증명하지는 못해요.')]), 'os1568': ('같은 양식의 이름표가 수백 장 필요하면 한 장씩 손으로 쓰기보다 명단과 양식을 이용해 만들 수 있어요. 원자 연산 헤더도 생성기가 규칙에 따라 만든 파일이에요.', '코드를 생성하는 단계와 생성된 코드를 컴파일하고 호출하는 단계를 구별합니다.', '원천 표·도우미 → 쉘 생성기 → C 헤더 → 컴파일 → 원자 함수 호출의 순서도를 그리세요.', ['include/linux/atomic/atomic-long.h의 첫 부분에는 scripts/atomic/gen-atomic-long.sh가 생성했다는 안내와 직접 수정하지 말라는 안내가 있어요. generated는 다른 프로그램이 규칙에 따라 만들어 냈다는 뜻이에요.', 'generator, 즉 생성기는 원천 정보와 양식을 읽어서 결과 코드를 만드는 도구예요. 이 쉘 스크립트는 atomic-tbl.sh 도우미를 불러 반환 자료형, 인자와 이름 등을 구성하고 C 함수 글자를 출력해요.', '예를 들어 CONFIG_64BIT이면 raw_atomic64 계열을 부르고, 다른 분기이면 raw_atomic 계열을 부르는 wrapper를 만들어요. wrapper는 다른 함수를 감싸서 호출을 전달하는 함수예요. 인자 포인터를 알맞은 형식으로 바꾸는 코드도 생성해요.', '같은 모양의 함수를 여러 번 직접 적으면 한쪽 이름이나 인자를 잘못 고치기 쉬워요. 공통 규칙으로 생성하면 이런 반복 부분을 일관되게 만들 수 있어요. 그래도 생성 규칙 자체가 맞는지와 결과가 맞는지는 확인해야 해요.', '쉘 생성기를 실행해서 C 헤더를 만드는 단계와, C를 컴파일해 커널에서 호출하는 단계는 달라요. 원자적 더하기를 할 때마다 쉘 스크립트를 실행하는 것이 아니에요. 생성 결과가 미리 준비된 뒤 컴파일에 사용돼요.', '학습할 때는 원문을 보존하고 학습실의 메모에 설명을 붙이세요. 실제 구현을 바꾸려면 생성된 결과만 고치기보다 원천 표·생성기와 프로젝트의 재생성 절차를 확인해야 해요. 결과만 손으로 고치면 다시 생성할 때 그 수정이 사라질 수 있어요.'], [('이 헤더는 사람이 결과 파일을 직접 수정하라고 안내하나요?', ['네. 생성기와 관계없는 수작업 파일이에요', '아니요. 생성된 파일이며 직접 수정하지 말라는 안내가 있어요'], '정답은 두 번째예요. 파일 처음의 Generated by와 DO NOT MODIFY 안내가 단서예요. 구현을 고칠 때는 원천과 생성 절차를 확인해야 해요.'), ('쉘 생성기와 생성된 C 함수는 언제 실행되나요?', ['코드 생성과 컴파일·실행은 다른 단계예요', '원자 함수를 부를 때마다 쉘 생성기가 함께 실행돼요'], '정답은 첫 번째예요. 생성기는 C 코드를 미리 만드는 도구예요. 커널이 원자 연산을 할 때마다 헤더를 다시 만드는 것이 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_387.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
